#include <iostream>
#include <algorithm>
#include <cstdio>
#include <cstring>
using namespace std;

int n_value, k_value, p_value;

int fastExponentiation(int base, int exponent) {
    int result = 1;
    int current_power = base;
    while (exponent > 0) {
        if (exponent & 1) result = (long long)result * current_power % p_value;
        current_power = (long long)current_power * current_power % p_value;
        exponent >>= 1;
    }
    return result;
}

int extractLowbit(int x) {
    return x & (-x);
}

int cache[26][250010];
int factorials[250010], inv_factorials[250010];

void prepare() {
    factorials[0] = 1;
    for (int i = 1; i <= n_value; ++i)
        factorials[i] = (long long)factorials[i - 1] * i % p_value;
    inv_factorials[n_value] = fastExponentiation(factorials[n_value], p_value - 2);
    for (int i = n_value; i >= 1; --i)
        inv_factorials[i - 1] = (long long)inv_factorials[i] * i % p_value;
}

int recursiveCompute(int current, int S) {
    if (cache[current][S] != -1) return cache[current][S];
    if (S == 0) {
        cache[current][S] = factorials[n_value];
        for (int i = 1; i <= current; ++i)
            cache[current][S] = (long long)cache[current][S] * (k_value - i + 1) % p_value;
        return cache[current][S];
    }
    cache[current][S] = 0;
    int U = S - extractLowbit(S);
    for (int T = U; T; T = (T - 1) & U)
        cache[current][S] = (cache[current][S] + (long long)inv_factorials[S - T] * recursiveCompute(current + 1, T)) % p_value;
    cache[current][S] = (cache[current][S] + (long long)inv_factorials[S] * recursiveCompute(current + 1, 0)) % p_value;
    return cache[current][S];
}

int main() {
    scanf("%d %d %d", &n_value, &k_value, &p_value);
    int ans = 1;
    for (int i = 1; i <= n_value; ++i)
        ans = (long long)ans * k_value % p_value;
    if (n_value % 2 == 0) {
        prepare();
        memset(cache, -1, sizeof(cache));
        ans = (ans - recursiveCompute(0, n_value) + p_value) % p_value;
    }
    printf("%d\n", ans);
    return 0;
}
